import sys
import time
import threading

from shiny import App, ui, render, reactive, Inputs, Outputs, Session
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import pandas as pd
import numpy as np

# Detect Pyodide environment
def is_pyodide():
    try:
        import js  # pyodide-specific
        return True
    except ImportError:
        return False

# Fake psutil for Pyodide
class FakePsutil:
    def __init__(self):
        self._usage = 50.0

    def cpu_percent(self, interval=None):
        # Simulate CPU usage with some noise
        self._usage += np.random.randn() * 2
        self._usage = np.clip(self._usage, 0, 100)
        return round(self._usage, 2)

if is_pyodide():
    psutil = FakePsutil()
else:
    import psutil

colormaps = sorted(m for m in plt.colormaps() if not m.endswith("_r"))

app_ui = ui.page_fluid(
    ui.h2("CPU Usage Monitor"),
    ui.layout_sidebar(
        ui.panel_sidebar(
            ui.input_select("colormap", "Colormap", choices=colormaps, selected="viridis"),
            ui.input_numeric("samples", "Samples per graph", 30, min=5, max=200),
            ui.input_numeric("rows", "Rows in table", 10, min=1, max=200),
            ui.input_checkbox("freeze", "Freeze output", False),
            ui.input_action_button("clear", "Clear history"),
        ),
        ui.panel_main(
            ui.output_plot("cpu_plot"),
            ui.output_data_frame("cpu_table"),
        ),
    ),
)

def hide_ticks(ax):
    ax.set_xticks([])
    ax.set_yticks([])

def server(input: Inputs, output: Outputs, session: Session):
    # Store CPU usage history
    cpu_history = reactive.Value([])

    @reactive.Effect
    @reactive.event(input.clear)
    def _():
        cpu_history.set([])

    @reactive.Effect
    def _():
        if input.freeze():
            return
        samples = input.samples()
        history = cpu_history.get()
        if len(history) >= samples:
            history = history[-samples:]
        # Get new CPU usage
        if is_pyodide():
            usage = psutil.cpu_percent()
        else:
            usage = psutil.cpu_percent(interval=None)
        history.append({"time": time.strftime("%H:%M:%S"), "cpu": usage})
        cpu_history.set(history)
        # Sleep for a short interval to avoid flooding
        time.sleep(0.5)

    @output
    @render.plot
    def cpu_plot():
        history = cpu_history.get()
        if not history:
            fig, ax = plt.subplots()
            ax.text(0.5, 0.5, "No data", ha="center", va="center")
            hide_ticks(ax)
            return fig
        df = pd.DataFrame(history)
        fig, ax = plt.subplots(figsize=(6, 3))
        cmap = plt.get_cmap(input.colormap())
        normed = np.array(df["cpu"]) / 100
        colors = cmap(normed)
        ax.bar(df["time"], df["cpu"], color=colors)
        ax.set_ylim(0, 100)
        ax.set_ylabel("CPU Usage (%)")
        ax.set_xlabel("Time")
        hide_ticks(ax)
        plt.xticks(rotation=45, ha="right")
        plt.tight_layout()
        return fig

    @output
    @render.data_frame
    def cpu_table():
        history = cpu_history.get()
        if not history:
            return pd.DataFrame(columns=["Time", "CPU Usage (%)"])
        df = pd.DataFrame(history)
        df = df.rename(columns={"time": "Time", "cpu": "CPU Usage (%)"})
        return df.tail(input.rows())

app = App(app_ui, server)
